const data = $('Proses Meja Absen').first().json;
const jenis = data.jenis_absen || 'ABSEN';
const pgw   = data.pegawai || {};
const chatId = pgw.id || '';

const ikonJenis =
  jenis === 'MASUK'             ? '✅' :
  jenis === 'DI LUAR JAM MASUK' ? '⏰' :
  jenis === 'PULANG'            ? '🔵' :
  jenis === 'DI LUAR JAM PULANG'? '⚡' : '📋';

const jenisLabel =
  jenis === 'MASUK'             ? 'Masuk Tepat Waktu' :
  jenis === 'DI LUAR JAM MASUK'  ? 'Terlambat Masuk' :
  jenis === 'PULANG'             ? 'Pulang Tepat Waktu' :
  jenis === 'DI LUAR JAM PULANG' ? 'Pulang Lebih Awal' : jenis;

const text =
  `${ikonJenis} *ABSENSI BERHASIL DICATAT*\n` +
  `Halo, *${pgw.nama || '-'}*!\n\n` +
  `\ud83d\udccc *Jenis* : ${jenisLabel}\n` +
  `\ud83d\udc64 *NIP*   : ${pgw.nip || '-'}\n` +
  `\ud83d\udccd *Lokasi*: ${data.nama_lokasi || 'Meja Absen'}\n` +
  `\ud83d\udcc5 *Tgl*   : ${data.log.Tanggal || '-'}\n` +
  `\ud83d\udd52 *Waktu* : ${data.jam_bersih || '-'} WITA\n` +
  `\ud83d\udda5\ufe0f *Via*   : Meja Absen (Admin)\n\n` +
  `Terima kasih, selamat melanjutkan aktivitas!`;

return [{ json: { chat_id: chatId, text, jenis_absen: jenis, nama: pgw.nama || '-' }}];

const req        = $('Cek Admin Valid Meja').first().json;
const pegawaiRows= $('Get Pegawai Meja').all().map(i => i.json);
const logHariIni = $('Get Log Hari Ini Meja').all().map(i => i.json);
const jamRows    = $input.all().map(i => i.json);

const pegawai = pegawaiRows[0] || null;
if (!pegawai) {
  return [{ json: { ok:false, is_valid:false, message:`Pegawai dengan ID ${req.telegram_id} tidak ditemukan di database.` }}];
}

const jamAbsenRow = jamRows.find(r => r.key === 'jam_absen_global') || jamRows[0] || {};

function parseHHMM(s) {
  const m = String(s||'').match(/(\d{1,2}):(\d{2})/);
  if (!m) return null;
  return parseInt(m[1])*60+parseInt(m[2]);
}

const BATAS_MASUK  = parseHHMM(jamAbsenRow.masuk)  ?? 8*60;
const BATAS_PULANG = parseHHMM(jamAbsenRow.pulang) ?? 14*60+30;
const TENGAH_HARI  = 12*60;

const totalMenit = parseHHMM(req.jam);
if (totalMenit === null) {
  return [{ json: { ok:false, is_valid:false, message:'Format jam tidak valid.' }}];
}

let jenisAbsen;
if      (totalMenit <= BATAS_MASUK)  jenisAbsen = 'MASUK';
else if (totalMenit <= TENGAH_HARI)  jenisAbsen = 'DI LUAR JAM MASUK';
else if (totalMenit <  BATAS_PULANG) jenisAbsen = 'DI LUAR JAM PULANG';
else                                 jenisAbsen = 'PULANG';

const GRP_MASUK  = ['MASUK','DI LUAR JAM MASUK'];
const GRP_PULANG = ['PULANG','DI LUAR JAM PULANG','PULANG LUAR'];

const sudahMasuk  = logHariIni.some(r => GRP_MASUK.includes(String(r['Jenis Absen']||r.jenis||'').toUpperCase().trim()));
const sudahPulang = logHariIni.some(r => GRP_PULANG.includes(String(r['Jenis Absen']||r.jenis||'').toUpperCase().trim()));

if (GRP_MASUK.includes(jenisAbsen)  && sudahMasuk)  return [{ json: { ok:false, is_valid:false, message:`${pegawai.nama||pegawai.username} sudah absen MASUK hari ini.` }}];
if (GRP_PULANG.includes(jenisAbsen) && sudahPulang) return [{ json: { ok:false, is_valid:false, message:`${pegawai.nama||pegawai.username} sudah absen PULANG hari ini.` }}];
if (GRP_PULANG.includes(jenisAbsen) && !sudahMasuk) return [{ json: { ok:false, is_valid:false, message:`${pegawai.nama||pegawai.username} belum absen MASUK hari ini.` }}];

const lat  = req.latitude  || 0;
const lng  = req.longitude || 0;
const lokasiNama = req.lokasi_nama || 'Meja Absen';
const koordinat  = (lat !== 0 && lng !== 0) ? `${lat},${lng}` : '-';
const jamBersih  = String(req.jam).split(' ')[0].substring(0, 5);

return [{ json: {
  ok: true, is_valid: true,
  jenis_absen: jenisAbsen,
  nama_lokasi: lokasiNama,
  koordinat,
  log: {
    ID        : String(req.telegram_id),
    instansi_id: pegawai.instansi_id || "bapperida",
    pangkat    : pegawai.pangkat || "",
    bidang     : pegawai.bidang || "",
    Nama      : pegawai.nama    || pegawai.username  || '-',
    NIP       : pegawai.NIP     || pegawai.nip       || '-',
    Tanggal   : req.tanggal,
    Jam       : jamBersih,
    Jenis_Absen: jenisAbsen,
    Lokasi    : lokasiNama,
    Ket       : `Meja Absen oleh Admin ID:${req.admin_id}`,
    koordinat
  },
  pegawai: {
    id     : String(req.telegram_id),
    nama   : pegawai.nama   || pegawai.username || '-',
    nip    : pegawai.NIP    || pegawai.nip      || '-',
    jabatan: pegawai.Jabatan|| pegawai.jabatan  || '-'
  },
  admin_id   : req.admin_id,
  jam_bersih : jamBersih
}}];

const validasi = $('Validasi Meja Absen').first().json;
const adminRows = $input.all().map(i => i.json);
const adminFound = adminRows.length > 0 && adminRows[0].telegram_id;
if (!adminFound) {
  return [{ json: { ok:false, is_admin:false, message:'Akses ditolak. Hanya admin yang boleh menggunakan Meja Absen.', ...validasi }}];
}
return [{ json: { ok:true, is_admin:true, ...validasi }}];

const body = $input.first().json.body || {};
const telegramId = String(body.telegram_id || '').trim();
const adminId    = body.admin_id ? String(body.admin_id) : null;
const jam        = String(body.jam || '').trim();
const tanggal    = String(body.tanggal_iso || '').trim();

if (!telegramId) return [{ json: { ok:false, is_valid:false, message:'telegram_id pegawai wajib diisi' }}];
if (!adminId)    return [{ json: { ok:false, is_valid:false, message:'admin_id wajib diisi' }}];
if (!jam)        return [{ json: { ok:false, is_valid:false, message:'jam wajib diisi' }}];
if (!tanggal)    return [{ json: { ok:false, is_valid:false, message:'tanggal_iso wajib diisi' }}];

return [{ json: {
  ok: true, is_valid: true,
  telegram_id: telegramId,
  admin_id: adminId,
  jam, tanggal,
  latitude: parseFloat(body.latitude) || 0,
  longitude: parseFloat(body.longitude) || 0,
  accuracy: parseFloat(body.accuracy) || 0,
  lokasi_nama: body.lokasi_nama || 'Meja Absen'
}}];

const method=$input.first().json.headers?.['x-forwarded-method']||$input.first().json.method||'';
if(method==='OPTIONS'){$execution.respond({statusCode:200,headers:{'Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'POST,OPTIONS','Access-Control-Allow-Headers':'Content-Type,ngrok-skip-browser-warning,Accept'},body:''});return[];}
return $input.all();

const rows = $input.all().map(i => i.json);
const result = rows
  .filter(r => r.face_histogram && r.face_histogram !== '[]' && r.face_histogram !== '')
  .map(r => {
    let descriptor = null;
    try { descriptor = JSON.parse(r.face_histogram); } catch(_) {}
    if (!descriptor || !Array.isArray(descriptor) || !descriptor.length) return null;
    const tid = r.id || r.ID;
    if (!tid) return null;
    return {
      telegram_id: String(tid),
      descriptor,
      face_model: r.face_model || (descriptor.length >= 512 ? 'human' : 'faceapi'),
      dataUrl: r.face_photo || null,
      foto_base64: r.face_photo || null,
      savedAt: r.face_saved_at || null,
      nama: r.nama || r.Nama || r.username || String(tid),
      nip: r.NIP || r.nip || '',
      no: r.no
    };
  })
  .filter(Boolean);
return [{ json: { ok: true, data: result, count: result.length } }];

const method=$input.first().json.headers?.['x-forwarded-method']||$input.first().json.method||'';
if(method==='OPTIONS'){$execution.respond({statusCode:200,headers:{'Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'GET,OPTIONS','Access-Control-Allow-Headers':'Content-Type,ngrok-skip-browser-warning,Accept'},body:''});return[];}
return $input.all();

const method=$input.first().json.headers?.['x-forwarded-method']||$input.first().json.method||'';
if(method==='OPTIONS'){$execution.respond({statusCode:200,headers:{'Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'GET,POST,OPTIONS','Access-Control-Allow-Headers':'Content-Type,ngrok-skip-browser-warning,Accept'},body:''});return[];}
return $input.all();

const rows = $input.all().map(i => i.json);
if (!rows.length || !rows[0].signature) {
  return [{json:{ok:false,message:'Belum ada tanda tangan',signature:null}}];
}
const row = rows[0];
return [{json:{ok:true,telegram_id:row.telegram_id,
  signature:row.signature,saved_at:row.saved_at,saved_by:row.saved_by}}];

const method=$input.first().json.headers?.['x-forwarded-method']||$input.first().json.method||'';
if(method==='OPTIONS'){$execution.respond({statusCode:200,headers:{'Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'GET,POST,OPTIONS','Access-Control-Allow-Headers':'Content-Type,ngrok-skip-browser-warning,Accept'},body:''});return[];}
return $input.all();

const input = $input.first().json;
const body   = input.body || input;
if (input.isOptions) return [{json:{isOptions:true}}];

const telegram_id = String(body.telegram_id || '').trim();
const signature   = String(body.signature || '').trim();
const saved_at    = body.savedAt || new Date().toISOString();
const saved_by    = body.savedBy ? Number(body.savedBy) : null;

if (!telegram_id) return [{json:{error:true,message:'telegram_id wajib diisi'}}];
if (!signature)   return [{json:{error:true,message:'signature wajib diisi'}}];

return [{json:{
  telegram_id: Number(telegram_id),
  signature,
  saved_at,
  saved_by,
  error: false
}}];

const method=$input.first().json.headers?.['x-forwarded-method']||$input.first().json.method||'';
if(method==='OPTIONS'){$execution.respond({statusCode:200,headers:{'Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'GET,POST,OPTIONS','Access-Control-Allow-Headers':'Content-Type,ngrok-skip-browser-warning,Accept'},body:''});return[];}
return $input.all();

const d = $('Auto Approve (S, T, TUBEL, CUTI)').first().json;
const jenis = d.row_jenis_base;
const em = { IZIN: '🙏', SAKIT: '🤒', TUGAS: '💼' }[jenis] || '📝';
const isApprove = d.action === 'APPROVE';
const icon = isApprove ? '✅' : '❌';
const label = isApprove ? 'DISETUJUI' : 'DITOLAK';
const text = `DIINFORMASIKAN BAHWA
━━━━━━━━━━━━━━━━━━
${em} *${jenis}* — ${d.tgl_range}
👤 *${d.row_nama}*
📝 ${d.row_ket || '—'}
━━━━━━━━━━━━━━━━━━
_Pengumuman dari Admin BAPPERIDA Sumba Barat_`;

const pegawai = $input.all().map(i => i.json).filter(p => {
  const id = String(p.id || '').trim();
  const st = String(p.Status || p.status || 'AKTIF').toUpperCase();
  return id && st !== 'NONAKTIF' && st !== 'INACTIVE';
});

return pegawai.map(p => ({ json: { chat_id: String(p.id), text } }));

const d = $input.first().json;

const dates = (d.dates && d.dates.length) ? d.dates : [d.row_tgl_mulai].filter(Boolean);
if (!dates.length) return [{json:{...d, tanggal_this:'', id_ket: (d.target_id_ket||'UNK') + '_01'}}];

const prefixMap = { IZIN:'IZN', SAKIT:'SKT', TUGAS:'TGS' };
const jenisBase = (d.row_jenis_base||'').toUpperCase();
const prefix = prefixMap[jenisBase] || jenisBase.slice(0,3);
const tglKey = (d.row_tgl_mulai||'').replace(/-/g,'');

const out = [];
dates.forEach((tgl, i) => {
  const suffix = String(i+1).padStart(2,'0');
  // 1. Catat Keterangan Utama (IZIN/SAKIT/TUGAS)
  out.push({
    json: {
      ...d,
      tanggal_this: tgl,
      id_ket: `${prefix}${tglKey}_${d.row_id}_${suffix}`
    }
  });

  // 2. Jika IZIN dan Selesai >= 14:30, Otomatis Catat PULANG
  const jamSelesai = d.row_jam_selesai || '';
  if (jenisBase === 'IZIN' && jamSelesai >= '14:30') {
    out.push({
      json: {
        ...d,
        tanggal_this: tgl,
        row_jenis_base: 'PULANG',
        row_jam: jamSelesai,
        row_ket: `${d.row_ket} (Auto Pulang dari Izin Jam)`,
        id_ket: `PLG${tglKey}_${d.row_id}_${suffix}`
      }
    });
  }
});
return out;

const d = $input.first().json;
// ket_temp = 1 row per pengajuan, matching = [ID_Ket]
const rows = Array.isArray(d.matching_ket_rows) ? d.matching_ket_rows.flat().map(String).filter(Boolean) : [String(d.target_id_ket)];
return rows.map(idKet => ({ json: { ...d, target_id_ket: idKet } }));

const d=$input.first().json;
if(!d.ok) return [{json:d}];
const AUTO=['SAKIT','TUGAS','TUBEL','CUTI'];
if(AUTO.includes(d.row_jenis_base)) return [{json:{...d,action:'APPROVE',new_jenis_absen:d.row_jenis_base,_auto:true}}];
return [{json:d}];

const idKetRaw = $('Validasi Approve').item.json.id_ket;
const action   = $('Validasi Approve').item.json.action;
const jenis    = $('Validasi Approve').item.json.jenis;
const allRows  = $input.all();

// Normalisasi: strip suffix _01/_02 jika ada (ket_temp simpan tanpa suffix)
const idKet = String(idKetRaw).replace(/_\d{2}$/, '');

const match = allRows.find(r => String(r.json.ID_Ket||'').trim() === idKet.trim());
if (!match) return [{json:{ok:false, message:'Data tidak ditemukan di ket_temp.'}}];

const r = match.json;

const tglMulai   = r.tgl_mulai || '';
const tglSelesai = r.tgl_selesai || tglMulai;
const tglRange   = r.tanggal || (tglMulai === tglSelesai ? tglMulai : `${tglMulai} s.d. ${tglSelesai}`);

// Generate dates dari tgl_mulai sampai tgl_selesai
const dates = [];
if (tglMulai) {
  const start = new Date(tglMulai), end = new Date(tglSelesai||tglMulai);
  for (let d = new Date(start); d <= end; d.setDate(d.getDate()+1))
    dates.push(d.toISOString().split('T')[0]);
}
if (!dates.length) dates.push(tglMulai);

const nowStr = new Date().toLocaleString('en-US', {timeZone:'Asia/Makassar', hour12:false});
const now    = new Date(nowStr);
const tsStr  = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')} ${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;

const newStatus     = action === 'APPROVE' ? 'DISETUJUI' : 'DITOLAK';
const newJenisAbsen = action === 'APPROVE' ? jenis : jenis + ' DITOLAK';

return [{json:{
  ok:                true,
  target_id_ket:     idKet,
  matching_ket_rows: [idKet],
  dates,
  tgl_range:         tglRange,
  new_status:        newStatus,
  new_jenis_absen:   newJenisAbsen,
  action,
  row_id:            String(r.ID_Pegawai || r.telegram_id || ''),
  row_nama:          r.Nama || r.nama || '',
  row_nip:           r.NIP  || r.nip  || '',
  row_tgl_mulai:     tglMulai,
  row_tgl_selesai:   tglSelesai,
  row_jam:           r.Jam || r.diajukan_at || tsStr.split(' ')[1],
  row_ket:           r.Ket || r.keterangan || '',
  row_jenis_base:    jenis,
  timestamp:         tsStr
}}];

const body=$('CORS Ket Approve').first().json.body||{};
let ADMIN_IDS=[];
try{
  const adminRows=$('Get Admin List Approve').all().map(i=>i.json);
  ADMIN_IDS=adminRows.map(r=>parseInt(r.telegram_id||r.Telegram_ID||r.telegram_Id||0)).filter(id=>id>0);
}catch(_){}
if(!ADMIN_IDS.length) ADMIN_IDS=[1383864355];
const adminId=parseInt(body.admin_id||0);
if(!ADMIN_IDS.includes(adminId)) return [{json:{ok:false,message:'Akses ditolak. Bukan admin.'}}];
const action=(body.action||'').toUpperCase();
if(!['APPROVE','REJECT'].includes(action)) return [{json:{ok:false,message:'Action tidak valid.'}}];
const idKetApprove=String(body.id_ket||'').trim();
if(!idKetApprove) return [{json:{ok:false,message:'id_ket wajib ada.'}}];
const jenis=(body.jenis||'').toUpperCase();
if(!jenis) return [{json:{ok:false,message:'jenis wajib ada.'}}];
return [{json:{ok:true,id_ket:idKetApprove,admin_id:adminId,action,jenis,tanggal:body.tanggal||''}}];

const method=$input.first().json.headers?.['x-forwarded-method']||$input.first().json.method||'';
if(method==='OPTIONS'){$execution.respond({statusCode:200,headers:{'Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'GET,POST,OPTIONS','Access-Control-Allow-Headers':'Content-Type,ngrok-skip-browser-warning,Accept'},body:''});return[];}
return $input.all();

const VALID_JENIS = ['IZIN', 'SAKIT', 'TUGAS'];

const rows = $input.all()
  .map(i => {
    const r = i.json;

    // Normalisasi field — handle schema baru (Supabase) dan lama (GSheets)
    const id_ket     = r.ID_Ket      || r.id_ket     || '';
    const user_id    = String(r.telegram_id || r.ID_Pegawai || r.ID || r.id || '').trim();
    const nama       = r.nama        || r.Nama        || '';
    const nip        = r.nip         || r.NIP         || '';
    const tanggal    = r.tanggal     || r.Tanggal     || '';
    const jam        = r.diajukan_at || r.Jam         || '';
    const jenis_raw  = String(r.jenis || r['Jenis Absen'] || r.jenis_absen || '').trim().toUpperCase();
    const keterangan = r.keterangan  || r.Ket         || '';
    const status     = String(r.status || r.Status    || '').trim();

    // Buang row yang tidak punya user_id atau jenis valid
    if (!user_id || !jenis_raw) return null;

    // Normalisasi jenis: hapus suffix status (PENDING, DITOLAK, DISETUJUI)
    const jenis_base = jenis_raw
      .replace(' PENDING','').replace(' DITOLAK','')
      .replace(' TOLAK','').replace(' DISETUJUI','').trim();
    if (!VALID_JENIS.includes(jenis_base)) return null;

    return {
      id_ket,
      user_id,
      nama,
      nip,
      tanggal,
      jam,
      jenis: jenis_base,
      keterangan,
      status,
    };
  })
  .filter(Boolean);

return [{ json: { ok: true, data: rows, count: rows.length } }];

const q = $input.first().json.query || $input.first().json.params || {};
const userId       = String(q.user_id || '').trim();
const statusFilter = String(q.status  || '').trim().toUpperCase();
// Admin request: ada is_admin=true atau tidak ada user_id tapi ada status filter
const isAdmin = q.is_admin === 'true' || q.is_admin === true || (!userId && statusFilter === 'PENDING');
return [{ json: {
  user_id:          userId,
  status_filter:    statusFilter,
  is_admin_request: isAdmin
} }];

const method=$input.first().json.headers?.['x-forwarded-method']||$input.first().json.method||'';
if(method==='OPTIONS'){$execution.respond({statusCode:200,headers:{'Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'GET,POST,OPTIONS','Access-Control-Allow-Headers':'Content-Type,ngrok-skip-browser-warning,Accept'},body:''});return[];}
return $input.all();

const idKet  = $('Parse Delete').item.json.id_ket;
const userId = $('Parse Delete').item.json.user_id;
const allRows = $input.all();
const match = allRows.find(r =>
  String(r.json.ID_Ket||'').trim() === String(idKet).trim() &&
  String(r.json.telegram_id||'').trim() === String(userId).trim()
);
if (!match) return [{json:{ok:false,message:'Data tidak ditemukan atau bukan milik Anda.'}}];
if ((match.json.status||'').toUpperCase() !== 'PENDING')
  return [{json:{ok:false,message:'Hanya keterangan PENDING yang bisa dihapus.'}}];
const tglMulai   = String(match.json.tanggal||$('Parse Delete').first().json.tgl_mulai||'');
const tglSelesai = String($('Parse Delete').first().json.tgl_selesai||tglMulai);
const dates=[];
for(let d=new Date(tglMulai),e=new Date(tglSelesai);d<=e;d.setDate(d.getDate()+1))
  dates.push(d.toISOString().split('T')[0]);
const idPrefix = String(idKet).split('_').slice(0,2).join('_');
const idsToDelete = allRows.filter(r=>String(r.json.ID_Ket||'').startsWith(idPrefix)).map(r=>String(r.json.ID_Ket));
return [{json:{...match.json,ok:true,user_id:userId,ket_temp_row:idKet,ids_to_delete:idsToDelete,dates}}];

const d=$input.first().json;
const ids=d.ids_to_delete||[d.ket_temp_row];
if(!ids.length) return [{json:{...d,_id_ket_to_delete:d.ket_temp_row,_skip_log:true}}];
return ids.map((idKet,i)=>({json:{...d,_id_ket_to_delete:idKet,_is_last:i===ids.length-1}}));

const verif=$('Verifikasi Row1').first().json;
const idPrefix=verif.ids_to_delete?String(verif.ID_Ket||verif.id_ket||'').split('_').slice(0,2).join('_'):'';
return [{json:{...verif,id_ket_prefix:idPrefix,ids_to_delete:verif.ids_to_delete||[verif.ket_temp_row],row_numbers_to_delete:[]}}];

const body=$input.first().json.body||{};
const userId=String(body.user_id||'').trim();
const rowNum=parseInt(body.row_number||0);
const tglMulai=String(body.tgl_mulai||body.tanggal||'').trim();
const tglSelesai=String(body.tgl_selesai||body.tanggal||'').trim();
if(!userId) return [{json:{ok:false,message:'user_id wajib ada.'}}];
