let lokasiValid   = null;  // lokasi yang lolos radius + IP
let lokasiIPGagal = null;  // lokasi yang lolos radius tapi IP tidak cocok

// Perbaikan 3: Bypass Radius & IP jika absen dilakukan via Meja Absen (Admin)
