  lokasiValid = body.lokasi_nama || 'Meja Absen';
} else {
  if (!lokasiItems.length) return tolak('LOKASI_TIDAK_ADA', 'Data lokasi kantor belum dikonfigurasi.');

  const accuracyBuffer = Math.min(accuracy, 50);

  for (const lok of lokasiItems) {
    const namaLok = lok.Nama_Lokasi || lok.nama_lokasi || 'Kantor';
    const jarak   = haversine(lat, lng, parseFloat(lok.latitude), parseFloat(lok.longitude));

    // Di luar radius → lewati
    if (jarak > (parseFloat(lok.radius) || 100) + accuracyBuffer) continue;

    // Dalam radius: cek ip_range jika kolom diisi
    const ipRangeRaw = String(lok.ip_range || '').trim();

    if (ipRangeRaw) {
      if (!ipCek) {
        return tolak('IP_TIDAK_TERDETEKSI', `Lokasi ${namaLok} memerlukan jaringan kantor tetapi alamat IP Anda tidak dapat dideteksi.`);
      }

      const rangeList = ipRangeRaw.split(',').map(s => s.trim()).filter(Boolean);
      if (!rangeList.some(cidr => ipInCIDR(ipCek, cidr))) {
        lokasiIPGagal = lokasiIPGagal || namaLok;
        continue;
      }
    }

    lokasiValid = namaLok;
    break;
  }

  if (!lokasiValid) {
    if (lokasiIPGagal) {
      return tolak('BUKAN_JARINGAN_KANTOR', `Anda berada di area ${lokasiIPGagal} namun bukan dari jaringan WiFi kantor yang diizinkan. IP Anda: ${ipCek}.`);
    }
    let jarakMin = Infinity, namaMin = '';
    for (const lok of lokasiItems) {
      const j = haversine(lat, lng, parseFloat(lok.latitude), parseFloat(lok.longitude));
      if (j < jarakMin) { jarakMin = j; namaMin = lok.Nama_Lokasi || lok.nama_lokasi || 'Kantor'; }
    }
    return tolak('DILUAR_RADIUS', `Anda berada ${Math.round(jarakMin)}m dari ${namaMin}. Absen hanya bisa di area kantor.`);
  }
}

